con:mockService.con:onRequestScript:
import com.eviware.soapui.impl.wsdl.support.wsdl.WsdlContext
import com.eviware.soapui.impl.wsdl.support.wsdl.WsdlValidator
import com.eviware.soapui.impl.wsdl.panels.mockoperation.WsdlMockRequestMessageExchange

def wsdlcontext = context.mockService.getMockedInterfaces()[0].getDefinitionContext() 
def validator = new com.eviware.soapui.impl.wsdl.support.wsdl.WsdlValidator(wsdlcontext);

def operation = mockRequest.soapAction.substring(mockRequest.soapAction.lastIndexOf('/') +1)
log.info  context.mockService.toString() + "::" + operation
def wsdlMockOperation = context.mockService.getMockOperationByName(operation)

con:mockOperation.con:dispatchPath:
import com.eviware.soapui.impl.wsdl.support.wsdl.WsdlContext
import com.eviware.soapui.impl.wsdl.support.wsdl.WsdlValidator
import com.eviware.soapui.impl.wsdl.panels.mockoperation.WsdlMockRequestMessageExchange
import com.eviware.soapui.support.XmlHolder

def mockService = mockOperation.mockService

def wsdlcontext = context.mockService.getMockedInterfaces()[0].getDefinitionContext();
def validator = new WsdlValidator(wsdlcontext);
def msgExchange = new WsdlMockRequestMessageExchange(mockRequest, mockOperation); 
def errors = validator.assertRequest(msgExchange, false);

def msg = ""
if (errors.length > 0) {
    errors.each {
        log.error("Incoming request contains error ${it.toString()}")
        msg += "${it.toString()}\n"
    }
    context.validationMessages = msg
    return "SoapFault"
}

def holder = new XmlHolder( mockRequest.requestContent )
def domain = 'infrastructure:directory:employee'
def interaction = 'GetEmployeeIncludingProtectedPerson'
def version = '4'
holder.namespaces['soapenv'] = 'http://schemas.xmlsoap.org/soap/envelope/'
holder.namespaces['urn'] = 'urn:riv:itintegration:registry:1'
holder.namespaces['urn1'] = 'urn:riv:' + domain + ':' + interaction + 'Responder:' + version
holder.namespaces['urn2'] = 'urn:riv:' + domain + ':' + version

def personHsaId = holder.getNodeValue('/soapenv:Envelope/soapenv:Body/urn1:' + interaction + '/urn1:personHsaId')

context.personHsaId = personHsaId ?: "MOCK-111222333444555"
log.info("personHsaId: " + personHsaId)

def responseName = mockRequest.requestHeaders['x-mock-response'][0]
log.info("responseName: ${responseName}")

return responseName
